    rows=[]; chars=[]
    for line in r.stdout.decode().splitlines():
        rows.append([tuple(map(int,v.split(';'))) for v in re.findall(r'38;2;(\d+;\d+;\d+)m',line)])
        chars.append(re.sub(r'\x1b\[[0-9;]*m','',line))
    return rows,chars

def block_avg(img,outW,outH):
    # requires divisible
    H=len(img); W=len(img[0]); bx=W//outW; by=H//outH
    if bx*outW!=W or by*outH!=H or bx==0 or by==0: return None
    out=[]
    for oy in range(outH):
        row=[]
        for ox in range(outW):
            row.append(tuple(int(sum(img[oy*by+dy][ox*bx+dx][c] for dy in range(by) for dx in range(bx))/(bx*by)+0.5) for c in range(4)))
        out.append(row)
    return out

def pair_avg_rows(img):
    out=[]
    for y in range(0,len(img)-1,2):
        out.append([tuple(int((img[y][x][c]+img[y+1][x][c])/2+0.5) for c in range(4)) for x in range(len(img[0]))])
    return out

def metrics(exp,cand):
    if cand is None: return None
    cand=cand[:len(exp)]
    if len(cand)<len(exp) or any(len(cand[y])<len(exp[y]) for y in range(len(exp))): return None
    diff=sae=maxd=0; total=0
    for y in range(len(exp)):
        for x in range(len(exp[y])):
            for c in range(3):
                d=abs(exp[y][x][c]-cand[y][x][c]); total+=1; sae+=d; maxd=max(maxd,d)
                if d: diff+=1
    return (sae/total,diff,total,maxd)

random.seed(7)
for (w,h,tc,tr) in [(32,16,8,4),(13,11,7,3)]:
    img=[[(random.randrange(256),random.randrange(256),random.randrange(256),255) for x in range(w)] for y in range(h)]
    exp,chars=binary_fg(img,tc,tr)
    print(f"\nCASE {w}x{h}->{tc}x{tr} exp first {exp[0]} chars {chars}")
    results=[]
    # Stage A dimensions list based on terminal and source
    Awidths=sorted(set([tc,2*tc,3*tc,4*tc,2*tc+2,4*tc+2,w,2*w]))
    Aheights=sorted(set([tr,tr+1,2*tr,2*tr+2,2*(tr+1),4*tr,4*(tr+1),4*tr+4,h,2*h]))
    for Aw in Awidths:
        for Ah in Aheights:
            inter=resize_pass(img,Aw,Ah)
            cands={}
            cands['resize->(tc,tr+1)']=resize_pass(inter,tc,tr+1)
            cands['resize->(tc,tr)']=resize_pass(inter,tc,tr)
            cands['resize->classic pair']=pair_avg_rows(resize_pass(inter,tc,2*tr+2))
            if Aw%tc==0 and Ah%(tr+1)==0:
                cands['block->(tc,tr+1)']=block_avg(inter,tc,tr+1)
            if Aw%tc==0 and Ah%tr==0:
                cands['block->(tc,tr)']=block_avg(inter,tc,tr)
            for name,cand in cands.items():
                m=metrics(exp,cand)
                if m: results.append((m[0],m[3],m[1],f"A {Aw}x{Ah} {name}"))
    results.sort()
    for r in results[:20]:
        print(f" MAE {r[0]:.3f} max{r[1]} mism{r[2]} {r[3]}")
