        rows.append([tuple(map(int,v.split(';'))) for v in re.findall(r'38;2;(\d+;\d+;\d+)m',line)])
    return rows

def formulas(block):
    # block list 32 pixels in row-major
    out={}
    for c in range(3):
        pass
    def per_channel(fn):
        return tuple(fn([p[c] for p in block]) for c in range(3))
    out['round']=per_channel(lambda vs:(sum(vs)+16)//32)
    out['floor']=per_channel(lambda vs:sum(vs)//32)
    out['ceil']=per_channel(lambda vs:-(-sum(vs)//32))
    out['16bit_trunc_div_shr']=per_channel(lambda vs: ((sum(v*257 for v in vs)//32)>>8))
    out['16bit_exact']=per_channel(lambda vs: (sum(v*257 for v in vs)//(32*256)))
    out['16bit_round?']=per_channel(lambda vs: (((sum(v*257 for v in vs)+16)//32)>>8))
    # staged average rows: average each row of 4 (floor/round), then average 8 row avgs
    def staged(vs, mode):
        rows=[]
        for r in range(8):
            s=sum(vs[r*4:(r+1)*4])
            rows.append((s+2)//4 if mode=='round' else s//4)
        s=sum(rows)
        return (s+4)//8 if mode=='round' else s//8
    out['staged_row_round']=per_channel(lambda vs:staged(vs,'round'))
    out['staged_row_floor']=per_channel(lambda vs:staged(vs,'floor'))
    # staged by classic pairs: average 2 rows *4 cols = 8 pixels (floor/round), then average 4 pair avgs
    def staged_pair(vs,mode):
        pairs=[]
        for p in range(4):
            s=sum(vs[p*8:(p+1)*8]); pairs.append((s+4)//8 if mode=='round' else s//8)
        s=sum(pairs); return (s+2)//4 if mode=='round' else s//4
    out['pair_round']=per_channel(lambda vs:staged_pair(vs,'round'))
    out['pair_floor']=per_channel(lambda vs:staged_pair(vs,'floor'))
    # sequential running average integer: avg=0; for i,v enumerate: avg += (v-avg)//(i+1) but Go trunc toward zero for neg - python // floor differs; implement trunc
    def trunc_div(a,b):
        return int(a/b) if a>=0 else -((-a)//b)
    def seq(vs):
        avg=0
        for i,v in enumerate(vs):
            if i==0: avg=v
            else: avg=avg+trunc_div(v-avg,i+1)
        return avg
    out['seq_running']=per_channel(seq)
    # sequential pairwise mix (avg=(avg+v)//2 each time) unlikely
    def seqmix(vs):
        avg=vs[0]
        for v in vs[1:]: avg=(avg+v)//2
        return avg
    out['seq_mix_floor']=per_channel(seqmix)
    return out

