import sys; sys.path.insert(0,'/tmp/work')
from gen import write_png
import subprocess,re,random, struct, math
def f32(x): return struct.unpack('f',struct.pack('f',x))[0]
def binary(img):
    write_png("/tmp/work/tmp.png",32,32,img,6)
    r=subprocess.run(["/workspace/executable","-s","2","-d","1","-tc","1000","-tr","1000","/tmp/work/tmp.png"],capture_output=True)
    return [[tuple(map(int,v.split(';'))) for v in re.findall(r'38;2;(\d+;\d+;\d+)m',line)] for line in r.stdout.decode().splitlines()]

def convert(x,mode):
    if mode=='round': return int(math.floor(x+0.5))
    if mode=='trunc': return int(x)
    if mode=='mathround': return int(math.floor(x+0.5)) # positive same

def candidates(vs):
    out={}
    # normalized f64 sum /32 *255 +0.5 trunc
    avg=sum(v/255 for v in vs)/32; out['f64_norm_round']=convert(avg*255,'round'); out['f64_norm_trunc']=convert(avg*255,'trunc')
    # sum of normalized rounded each? etc
    avg=sum(v/65535*257 for v in vs)/32 # same
    # float32 sequential sum normalized
    s=f32(0)
    for v in vs: s=f32(s+f32(v/255))
    avg32=f32(s/32); out['f32_norm_round']=convert(f32(avg32*255),'round'); out['f32_norm_trunc']=convert(f32(avg32*255),'trunc')
    # running average f64 normalized
    avg=0.0
    for i,v in enumerate(vs): avg += ((v/255)-avg)/(i+1)
    out['run_f64_norm_round']=convert(avg*255,'round')
    # running avg f64 unnormalized
    avg=0.0
    for i,v in enumerate(vs): avg += (v-avg)/(i+1)
    out['run_f64_round']=convert(avg,'round'); out['run_f64_trunc']=convert(avg,'trunc')
    # running avg f32 unnormalized
    avg=f32(0)
    for i,v in enumerate(vs): avg=f32(avg+f32((f32(v)-avg)/f32(i+1)))
    out['run_f32_round']=convert(avg,'round')
    # pairwise float avg normalized binary tree
    vals=[v/255 for v in vs]
    while len(vals)>1: vals=[(vals[i]+vals[i+1])/2 for i in range(0,len(vals),2)]
    out['pair_f64_norm_round']=convert(vals[0]*255,'round')
    # sum as f32 unnormalized /32
    s=f32(0)
    for v in vs: s=f32(s+f32(v))
    out['f32_sum_round']=convert(f32(s/32),'round')
    # average using 16-bit /256 conversion then *? : value each = (v*257)>>8 = v exact
    # average using /256 scale: x = (v*257)/256 float, avg, trunc
    avg=sum((v*257)/256 for v in vs)/32; out['scale256_trunc']=convert(avg,'trunc'); out['scale256_round']=convert(avg,'round')
    # average using Go color values / 257? r16/257 = v exact
    return out

random.seed(123); scores={}
