    if mode=='scale_round': return int(W*scale+0.5), int(H*scale+0.5)
    if mode=='ratio_floor':
        # src aspect vs target
        if W*th > H*tw: # wider, height = th, width proportional
            return int(W*th/H), th
        else:
            return tw, int(H*tw/W)
    if mode=='ratio_ceil':
        if W*th > H*tw: return math.ceil(W*th/H), th
        else: return tw, math.ceil(H*tw/W)
    if mode=='ratio_round':
        if W*th > H*tw: return int(W*th/H+0.5), th
        else: return tw, int(H*tw/W+0.5)
