def intermediate_dims(W,H,tw,th,mode):
    # modes compute iw,ih
    scale=max(tw/W, th/H)
    if mode=='scale_floor': return int(W*scale), int(H*scale)
    if mode=='scale_ceil': return math.ceil(W*scale), math.ceil(H*scale)
    if mode=='scale_round': return int(W*scale+0.5), int(H*scale+0.5)
    if mode=='ratio_floor':
        # src aspect vs target
        if W*th > H*tw: # wider, height = th, width proportional
            return int(W*th/H), th
        else:
            return tw, int(H*tw/W)
    if mode=='ratio_ceil':
        if W*th > H*tw: return math.ceil(W*th/H), th
        else: return tw, math.ceil(H*tw/W)
    if mode=='ratio_round':
        if W*th > H*tw: return int(W*th/H+0.5), th
        else: return tw, int(H*tw/W+0.5)
    if mode=='ratio_float_floor_alt':
        # compare ratios float maybe >=
        if W/H > tw/th: return int(th*W/H), th
        else: return tw,int(tw*H/W)
    raise

def score(exp,cand):
    if cand is None:return None
    staged=cand[2:]
    diff=tot=maxd=sae=0
    for y in range(len(exp)):
