import sys,math; sys.path.insert(0,'/tmp/work')
from gen import write_png
from candidate import weights
import subprocess,re,random

def clamp_round(v,maxv=255):
    return 0 if v<0 else maxv if v>maxv else int(v+0.5)
def resize_generic(img,dstW,dstH,maxv=255):
    # img pixels tuples numeric (float/int) channels, H pass then V, quantize/clamp round each pass to integer maxv if maxv integer
    srcH=len(img);srcW=len(img[0]); wx=weights(srcW,dstW); wy=weights(srcH,dstH)
    tmp=[]
    for y in range(srcH):
        row=[]
        for ws in wx:
            vals=[0.0]*4
            for i,w in ws:
                p=img[y][i]
                for c in range(4):vals[c]+=p[c]*w
            row.append(tuple(clamp_round(v,maxv) for v in vals))
        tmp.append(row)
    out=[]
    for ws in wy:
        row=[]
        for x in range(dstW):
            vals=[0.0]*4
            for i,w in ws:
                p=tmp[i][x]
                for c in range(4):vals[c]+=p[c]*w
            row.append(tuple(clamp_round(v,maxv) for v in vals))
        out.append(row)
    return out

def go_rgba16(c):
    r,g,b,a=c; return ((r*257)*a//255,(g*257)*a//255,(b*257)*a//255,a*257)
def go_p8(c):
    R,G,B,A=go_rgba16(c);return (R>>8,G>>8,B>>8,A>>8)
def direct_p8(c):
    r,g,b,a=c;return (r*a//255,g*a//255,b*a//255,a)
def blend_from_premult16(P,A,m):
    return tuple(((P[c] + (m[c]*257)*(65535-A)//65535)>>8) for c in range(3))
def blend_stage_nrgba(c,m):
    R,G,B,A=go_rgba16(c);return blend_from_premult16((R,G,B),A,m)
def blend_stage_rgba8(c,m):
    # c premult bytes; RGBA() => *257
    return blend_from_premult16(tuple(c[i]*257 for i in range(3)),c[3]*257,m)
def blend_stage_rgba64(c,m):
    return blend_from_premult16(c[:3],c[3],m)
def unpremult_go_nrgba(p8):
    # convert color.RGBA premult bytes to color.NRGBA via Go color model (approx exact stdlib logic)
    r,g,b,a=p8
    R=r*257;G=g*257;B=b*257;A=a*257
    if A==0:return (0,0,0,0)
    if A==65535:return (R>>8,G>>8,B>>8,255)
    # color.nrgbaModel: r = r * 0xffff / a ; then uint8(r>>8) likely
    return ((R*65535//A)>>8,(G*65535//A)>>8,(B*65535//A)>>8,A>>8)
def unpremult_float(p8,mode='trunc'):
    r,g,b,a=p8
    if a==0:return (0,0,0,0)
    out=[]
    for v in (r,g,b):
        x=v*255/a
        out.append(0 if x<0 else 255 if x>255 else (int(x+0.5) if mode=='round' else int(x)))
    return (*out,a)

def variants(img,tc,tr,m):
    dstW,dstH=tc,2*tr+2
    res={}
    # A go p8 resize, stage rgba
    stage=resize_generic([[go_p8(p) for p in row] for row in img],dstW,dstH,255)
    res['goP8_resize_rgbaStage']=[[blend_stage_rgba8(p,m) for p in row] for row in stage]
    # A go p8 resize, unpremult go, stage nRGBA
    stage2=[[unpremult_go_nrgba(p) for p in row] for row in stage]
    res['goP8_resize_unpremultGo']=[[blend_stage_nrgba(p,m) for p in row] for row in stage2]
    # direct p8
    stage=resize_generic([[direct_p8(p) for p in row] for row in img],dstW,dstH,255)
    res['directP8_resize_rgbaStage']=[[blend_stage_rgba8(p,m) for p in row] for row in stage]
    stage2=[[unpremult_go_nrgba(p) for p in row] for row in stage]
    res['directP8_resize_unpremultGo']=[[blend_stage_nrgba(p,m) for p in row] for row in stage2]
    for mode in ['trunc','round']:
        stage2=[[unpremult_float(p,mode) for p in row] for row in stage]
        res[f'directP8_resize_unpremultFloat{mode}']=[[blend_stage_nrgba(p,m) for p in row] for row in stage2]
    # 16 bit
    stage=resize_generic([[go_rgba16(p) for p in row] for row in img],dstW,dstH,65535)
    res['rgba64_resize']=[[blend_stage_rgba64(p,m) for p in row] for row in stage]
    # float exact premult products as input values scaled to bytes (v*a/255) resize_generic quantizes intermediate to byte round of premult sums.
    stage=resize_generic([[(p[0]*p[3]/255,p[1]*p[3]/255,p[2]*p[3]/255,p[3]) for p in row] for row in img],dstW,dstH,255)
    res['floatPremultInput_resize_rgbaStage']=[[blend_stage_rgba8(p,m) for p in row] for row in stage]
    stage2=[[unpremult_go_nrgba(p) for p in row] for row in stage]
    res['floatPremultInput_resize_unpremultGo']=[[blend_stage_nrgba(p,m) for p in row] for row in stage2]
    return res

def binary(img,tc,tr,mname):
    write_png("/tmp/work/tmp.png",len(img[0]),len(img),img,6)
    r=subprocess.run(["/workspace/executable","-m",mname,"-tc",str(tc),"-tr",str(tr),"/tmp/work/tmp.png"],capture_output=True)
    rows=[]
    for line in r.stdout.decode().splitlines():
        seq=[tuple(map(int,v.split(';'))) for v in re.findall(r'\[(?:48|38);2;(\d+;\d+;\d+)m',line)]; rows.append(seq[0::2]);rows.append(seq[1::2])
    return rows

