def clamp_round(v,maxv=255): return 0 if v<0 else maxv if v>maxv else int(v+0.5)
def clamp_trunc(v,maxv=255): return 0 if v<0 else maxv if v>maxv else int(v)
def go16(c):
    r,g,b,a=c; return ((r*257)*a//255,(g*257)*a//255,(b*257)*a//255,a*257)
def blend_nrgba(c,m):
    R,G,B,A=go16(c); return tuple(((P+(M*257)*(65535-A)//65535)>>8) for P,M in zip((R,G,B),m))

