    for sp in sumP:
        Pb=clamp_round(sp)
        if form=='go16':
            P16=Pb*257; A16=Aout*257; v=((P16*65535)//A16)>>8; out.append(min(255,v))
        elif form=='float_round_rawA':
            if sumA<=0: out.append(0)
            else: out.append(clamp_round(sp*255/sumA))
        elif form=='float_trunc_rawA':
            if sumA<=0: out.append(0)
            else: out.append(clamp_trunc(sp*255/sumA))
        elif form=='float_round_byteA': out.append(clamp_round(Pb*255/Aout))
        elif form=='float_trunc_byteA': out.append(clamp_trunc(Pb*255/Aout))
        elif form=='int_trunc_byte': out.append(min(255,(Pb*255)//Aout))
        elif form=='int_round_byte': out.append(min(255,(Pb*255+Aout//2)//Aout))
