package main

import (
	"image"
	"image/color"
	"image/draw"
	"math"
)

// toNRGBA converts any image to an 8-bit NRGBA image anchored at (0,0).
// It follows the behavior needed by the resizing code: source bounds
// offsets are honoured and the pixels are converted with the standard
// Go color model.
func toNRGBA(src image.Image) *image.NRGBA {
	if src == nil {
		return image.NewNRGBA(image.Rectangle{})
	}
	b := src.Bounds()
	w, h := b.Dx(), b.Dy()
	if w < 0 {
		w = 0
	}
	if h < 0 {
		h = 0
	}
	if n, ok := src.(*image.NRGBA); ok {
		if b.Min.X == 0 && b.Min.Y == 0 {
			out := *n
			out.Pix = append([]uint8(nil), n.Pix...)
			out.Rect = image.Rect(0, 0, w, h)
			return &out
		}
	}
	out := image.NewNRGBA(image.Rect(0, 0, w, h))
	draw.Draw(out, out.Bounds(), src, b.Min, draw.Src)
	return out
}

func cloneNRGBA(src *image.NRGBA) *image.NRGBA {
	if src == nil {
		return image.NewNRGBA(image.Rectangle{})
	}
	out := *src
	out.Pix = append([]uint8(nil), src.Pix...)
	return &out
}

type resizeWeight struct {
	index  int
	weight float64
}

func lanczosKernel(x float64) float64 {
	if x == 0 {
		return 1
	}
	if x <= -3 || x >= 3 {
		return 0
	}
	return (math.Sin(math.Pi*x) / (math.Pi * x)) * (math.Sin(math.Pi*x/3) / (math.Pi * x / 3))
}

func precomputeWeights(dstSize, srcSize int) [][]resizeWeight {
	if dstSize <= 0 || srcSize <= 0 {
		return nil
	}
	scale := float64(srcSize) / float64(dstSize)
	support := 3.0
	if scale > 1 {
		support *= scale
	}
	all := make([][]resizeWeight, dstSize)
	for dst := 0; dst < dstSize; dst++ {
		fx := (float64(dst) + 0.5) * scale
		start := int(math.Floor(fx - support))
		if start < 0 {
			start = 0
		}
		stop := int(math.Ceil(fx + support))
		if stop > srcSize {
			stop = srcSize
		}
		var ws []resizeWeight
		var sum float64
		for src := start; src < stop; src++ {
			dist := fx - (float64(src) + 0.5)
			scaled := dist
			if scale > 1 {
				scaled = dist / scale
			}
			w := lanczosKernel(scaled)
			if w != 0 {
				ws = append(ws, resizeWeight{index: src, weight: w})
				sum += w
			}
		}
		if sum != 0 {
			for i := range ws {
				ws[i].weight /= sum
			}
		}
		all[dst] = ws
	}
	return all
}

func clampByte(v float64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v + 0.5)
}

// resizeOnePass is an alpha-aware Lanczos resize in one dimension.
// Input is an NRGBA image. If horizontal is true, width changes and
// height is retained; otherwise height changes and width is retained.
// Premultiplied floating point channel values are accumulated and the
// result is unpremultiplied back to NRGBA bytes in each pass.
func resizeOnePass(src *image.NRGBA, dstW, dstH int, horizontal bool) *image.NRGBA {
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if srcW <= 0 || srcH <= 0 || dstW <= 0 || dstH <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, maxInt(dstW, 0), maxInt(dstH, 0)))
	}
	out := image.NewNRGBA(image.Rect(0, 0, dstW, dstH))
	if horizontal {
		weights := precomputeWeights(dstW, srcW)
		for y := 0; y < srcH; y++ {
			for x := 0; x < dstW; x++ {
				var sumR, sumG, sumB, sumA float64
				for _, w := range weights[x] {
					idx := y*src.Stride + w.index*4
					a := float64(src.Pix[idx+3])
					sumR += float64(src.Pix[idx+0]) * a / 255 * w.weight
					sumG += float64(src.Pix[idx+1]) * a / 255 * w.weight
					sumB += float64(src.Pix[idx+2]) * a / 255 * w.weight
					sumA += a * w.weight
				}
				oidx := y*out.Stride + x*4
				writeUnpremultiplied(out.Pix[oidx:oidx+4], sumR, sumG, sumB, sumA)
			}
		}
	} else {
		weights := precomputeWeights(dstH, srcH)
		for y := 0; y < dstH; y++ {
			for x := 0; x < srcW; x++ {
				var sumR, sumG, sumB, sumA float64
				for _, w := range weights[y] {
					idx := w.index*src.Stride + x*4
					a := float64(src.Pix[idx+3])
					sumR += float64(src.Pix[idx+0]) * a / 255 * w.weight
					sumG += float64(src.Pix[idx+1]) * a / 255 * w.weight
					sumB += float64(src.Pix[idx+2]) * a / 255 * w.weight
					sumA += a * w.weight
				}
				oidx := y*out.Stride + x*4
				writeUnpremultiplied(out.Pix[oidx:oidx+4], sumR, sumG, sumB, sumA)
			}
		}
	}
	return out
}

func writeUnpremultiplied(dst []uint8, sumR, sumG, sumB, sumA float64) {
	aout := clampByte(sumA)
	if aout == 0 {
		dst[0], dst[1], dst[2], dst[3] = 0, 0, 0, 0
		return
	}
	dst[0] = clampByte(sumR * 255 / sumA)
	dst[1] = clampByte(sumG * 255 / sumA)
	dst[2] = clampByte(sumB * 255 / sumA)
	dst[3] = aout
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// resizeNRGBA resizes src to dstW x dstH using the imaging behaviour
// identified from the reference program. A zero dimension preserves the
// aspect ratio; two zero dimensions return a clone. Callers are
// responsible for handling negative dimensions before this point in
// most paths, but this function returns a clone for them in order not
// to panic in cases modelled after imaging's early returns.
func resizeNRGBA(src *image.NRGBA, dstW, dstH int) *image.NRGBA {
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if srcW <= 0 || srcH <= 0 {
		return cloneNRGBA(src)
	}
	if dstW < 0 || dstH < 0 {
		return cloneNRGBA(src)
	}
	if dstW == 0 && dstH == 0 {
		return cloneNRGBA(src)
	}
	if dstW == 0 {
		dstW = int(math.Round(float64(srcW) * float64(dstH) / float64(srcH)))
	}
	if dstH == 0 {
		dstH = int(math.Round(float64(srcH) * float64(dstW) / float64(srcW)))
	}
	if dstW <= 0 || dstH <= 0 {
		// An aspect-preserving dimension can round to zero. Return an
		// empty image with the requested dimensions clamped at zero;
		// conversion code will turn this into the height/width error.
		return image.NewNRGBA(image.Rect(0, 0, maxInt(dstW, 0), maxInt(dstH, 0)))
	}
	if dstW == srcW && dstH == srcH {
		return cloneNRGBA(src)
	}
	tmp := resizeOnePass(src, dstW, srcH, true)
	return resizeOnePass(tmp, dstW, dstH, false)
}

func fitNRGBA(src *image.NRGBA, maxW, maxH int) *image.NRGBA {
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if srcW <= 0 || srcH <= 0 {
		return cloneNRGBA(src)
	}
	if maxW < 0 || maxH < 0 {
		return cloneNRGBA(src)
	}
	if srcW <= maxW && srcH <= maxH {
		return cloneNRGBA(src)
	}
	// Imaging's Fit was observed to truncate the proportional
	// dimension. Start from the width bound and then apply the
	// height bound if needed.
	newW := maxW
	newH := int(float64(srcH) * float64(maxW) / float64(srcW))
	if newH > maxH {
		newH = maxH
		newW = int(float64(srcW) * float64(maxH) / float64(srcH))
	}
	return resizeNRGBA(src, newW, newH)
}

func cropAnchorNRGBA(src *image.NRGBA, w, h int) *image.NRGBA {
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if w <= 0 || h <= 0 || srcW <= 0 || srcH <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, maxInt(w, 0), maxInt(h, 0)))
	}
	// Centre anchor. If the requested crop is larger than the source,
	// the imaging crop operation effectively intersects the crop
	// rectangle with the image; emulate that by clamping offsets and
	// dimensions to the available source.
	x0 := (srcW - w) / 2
	y0 := (srcH - h) / 2
	if x0 < 0 {
		x0 = 0
	}
	if y0 < 0 {
		y0 = 0
	}
	if x0 > srcW {
		x0 = srcW
	}
	if y0 > srcH {
		y0 = srcH
	}
	cw := w
	if x0+cw > srcW {
		cw = srcW - x0
	}
	ch := h
	if y0+ch > srcH {
		ch = srcH - y0
	}
	if cw < 0 {
		cw = 0
	}
	if ch < 0 {
		ch = 0
	}
	out := image.NewNRGBA(image.Rect(0, 0, cw, ch))
	for y := 0; y < ch; y++ {
		sidx := (y+y0)*src.Stride + x0*4
		didx := y * out.Stride
		copy(out.Pix[didx:didx+cw*4], src.Pix[sidx:sidx+cw*4])
	}
	return out
}

func fillNRGBA(src *image.NRGBA, w, h int) *image.NRGBA {
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if srcW <= 0 || srcH <= 0 {
		return cloneNRGBA(src)
	}
	if w < 0 || h < 0 {
		return cloneNRGBA(src)
	}
	// Calculate the intermediate size, rounding the proportional
	// dimension to the nearest integer (observed behaviour).
	var iw, ih int
	if float64(srcW)*float64(h) > float64(srcH)*float64(w) {
		// Source is wider than the target: height matches.
		ih = h
		iw = int(math.Round(float64(srcW) * float64(h) / float64(srcH)))
	} else {
		iw = w
		ih = int(math.Round(float64(srcH) * float64(w) / float64(srcW)))
	}
	resized := resizeNRGBA(src, iw, ih)
	return cropAnchorNRGBA(resized, w, h)
}

// Ensure color is referenced if future conversions need it; the draw
// package performs conversion above.
var _ = color.NRGBA{}
EOF

