package main

import (
	"errors"
	"fmt"
	"image"
	"image/color"
	"math"
	"strings"
)

type ditheringMode int
type scaleMode int

const (
	ditherNone ditheringMode = iota
	ditherBlocks
	ditherChars
)

const (
	scaleResize scaleMode = iota
	scaleFill
	scaleFit
)

var errANSImageSize = errors.New("ANSImage: height or width must be >=2")
var errDownloadFailed = errors.New("ANSImage: image download failed")

type ansImage struct {
	stage     *image.NRGBA
	blended   []uint8 // 3 bytes per stage pixel, matte-blended
	matte     color.RGBA
	dithering ditheringMode
	noBG      bool
}

func footprint(d ditheringMode) (int, int) {
	if d == ditherNone {
		return 1, 2
	}
	return 4, 8
}

func newScaledFromImage(src image.Image, cols, rows int, scaling scaleMode, dithering ditheringMode, matte color.RGBA, noBG bool) (*ansImage, error) {
	srcNRGBA := toNRGBA(src)
	fx, fy := footprint(dithering)
	targetW := cols * fx
	targetH := (rows + 1) * fy
	if targetW < 0 || targetH < 0 {
		return nil, errANSImageSize
	}
	var stage *image.NRGBA
	switch scaling {
	case scaleResize:
		stage = resizeNRGBA(srcNRGBA, targetW, targetH)
	case scaleFill:
		stage = fillNRGBA(srcNRGBA, targetW, targetH)
	case scaleFit:
		stage = fitNRGBA(srcNRGBA, targetW, targetH)
	default:
		stage = resizeNRGBA(srcNRGBA, targetW, targetH)
	}
	return newFromStage(stage, dithering, matte, noBG)
}

func newFromStage(stage *image.NRGBA, dithering ditheringMode, matte color.RGBA, noBG bool) (*ansImage, error) {
	w := stage.Bounds().Dx()
	h := stage.Bounds().Dy()
	if dithering == ditherNone {
		if w < 2 || h < 2 {
			return nil, errANSImageSize
		}
	} else {
		if w/4 < 2 || h/8 < 2 {
			return nil, errANSImageSize
		}
	}
	a := &ansImage{stage: stage, matte: matte, dithering: dithering, noBG: noBG}
	a.computeBlended()
	return a, nil
}

func blendPixel(c color.NRGBA, matte color.RGBA) (uint8, uint8, uint8) {
	r, g, b, a := c.RGBA()
	mr, mg, mb, _ := matte.RGBA()
	inv := uint32(0xffff - a)
	r = r + mr*inv/0xffff
	g = g + mg*inv/0xffff
	b = b + mb*inv/0xffff
	return uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)
}

func (a *ansImage) computeBlended() {
	w := a.stage.Bounds().Dx()
	h := a.stage.Bounds().Dy()
	if w <= 0 || h <= 0 {
		a.blended = nil
		return
	}
	a.blended = make([]uint8, w*h*3)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			idx := y*a.stage.Stride + x*4
			c := color.NRGBA{
				R: a.stage.Pix[idx+0],
				G: a.stage.Pix[idx+1],
				B: a.stage.Pix[idx+2],
				A: a.stage.Pix[idx+3],
			}
			r, g, b := blendPixel(c, a.matte)
			oidx := (y*w + x) * 3
			a.blended[oidx+0] = r
			a.blended[oidx+1] = g
			a.blended[oidx+2] = b
		}
	}
}

func (a *ansImage) pixel(x, y int) (uint8, uint8, uint8) {
	w := a.stage.Bounds().Dx()
	idx := (y*w + x) * 3
	return a.blended[idx], a.blended[idx+1], a.blended[idx+2]
}

func max3(r, g, b uint8) uint8 {
	m := r
	if g > m {
		m = g
	}
	if b > m {
		m = b
	}
	return m
}

