	// Sums are intentionally performed on values normalised to
	// float64 by /255, in row-major order. This reproduced the
	// reference output in exact .5 rounding cases.
	var sumR, sumG, sumB, sumBright float64
	for dy := 0; dy < 8; dy++ {
		for dx := 0; dx < 4; dx++ {
			r, g, b := a.pixel(cellX*4+dx, cellY*8+dy)
			sumR += float64(r) / 255
			sumG += float64(g) / 255
			sumB += float64(b) / 255
			sumBright += float64(max3(r, g, b)) / 255
		}
	}
	to8 := func(sum float64) uint8 {
		return uint8(math.Floor(sum/32*255 + 0.5))
	}
	return to8(sumR), to8(sumG), to8(sumB), to8(sumBright)
