	thresholds := []uint8{24, 47, 70, 93, 116, 139, 162, 185, 208, 231}
	chars := []rune{' ', '.', ':', ';', '+', '=', 'x', 'X', '$', '&', '#'}
	idx := 0
	for _, t := range thresholds {
		if brightness >= t {
			idx++
		}
	}
	return chars[idx]
}

