	noBG      bool
}

func footprint(d ditheringMode) (int, int) {
	if d == ditherNone {
		return 1, 2
	}
	return 4, 8
}

func newScaledFromImage(src image.Image, cols, rows int, scaling scaleMode, dithering ditheringMode, matte color.RGBA, noBG bool) (*ansImage, error) {
	srcNRGBA := toNRGBA(src)
	fx, fy := footprint(dithering)
	targetW := cols * fx
	targetH := (rows + 1) * fy
	if targetW < 0 || targetH < 0 {
		return nil, errANSImageSize
	}
	var stage *image.NRGBA
	switch scaling {
	case scaleResize:
		stage = resizeNRGBA(srcNRGBA, targetW, targetH)
	case scaleFill:
		stage = fillNRGBA(srcNRGBA, targetW, targetH)
	case scaleFit:
		stage = fitNRGBA(srcNRGBA, targetW, targetH)
	default:
		stage = resizeNRGBA(srcNRGBA, targetW, targetH)
	}
	return newFromStage(stage, dithering, matte, noBG)
}

func newFromStage(stage *image.NRGBA, dithering ditheringMode, matte color.RGBA, noBG bool) (*ansImage, error) {
	w := stage.Bounds().Dx()
	h := stage.Bounds().Dy()
	if dithering == ditherNone {
		if w < 2 || h < 2 {
			return nil, errANSImageSize
		}
	} else {
		if w/4 < 2 || h/8 < 2 {
			return nil, errANSImageSize
		}
	}
	a := &ansImage{stage: stage, matte: matte, dithering: dithering, noBG: noBG}
	a.computeBlended()
	return a, nil
}

func blendPixel(c color.NRGBA, matte color.RGBA) (uint8, uint8, uint8) {
	r, g, b, a := c.RGBA()
	mr, mg, mb, _ := matte.RGBA()
	inv := uint32(0xffff - a)
	r = r + mr*inv/0xffff
	g = g + mg*inv/0xffff
	b = b + mb*inv/0xffff
	return uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)
}

func (a *ansImage) computeBlended() {
	w := a.stage.Bounds().Dx()
	h := a.stage.Bounds().Dy()
	if w <= 0 || h <= 0 {
		a.blended = nil
		return
	}
	a.blended = make([]uint8, w*h*3)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			idx := y*a.stage.Stride + x*4
			c := color.NRGBA{
				R: a.stage.Pix[idx+0],
				G: a.stage.Pix[idx+1],
				B: a.stage.Pix[idx+2],
				A: a.stage.Pix[idx+3],
			}
			r, g, b := blendPixel(c, a.matte)
			oidx := (y*w + x) * 3
			a.blended[oidx+0] = r
			a.blended[oidx+1] = g
			a.blended[oidx+2] = b
		}
	}
}

func (a *ansImage) pixel(x, y int) (uint8, uint8, uint8) {
	w := a.stage.Bounds().Dx()
	idx := (y*w + x) * 3
	return a.blended[idx], a.blended[idx+1], a.blended[idx+2]
}

func max3(r, g, b uint8) uint8 {
	m := r
	if g > m {
		m = g
	}
	if b > m {
		m = b
	}
	return m
}

func blockAverageColor(a *ansImage, cellX, cellY int) (uint8, uint8, uint8, uint8) {
	// Sums are intentionally performed on values normalised to
	// float64 by /255, in row-major order. This reproduced the
	// reference output in exact .5 rounding cases.
	var sumR, sumG, sumB, sumBright float64
	for dy := 0; dy < 8; dy++ {
		for dx := 0; dx < 4; dx++ {
			r, g, b := a.pixel(cellX*4+dx, cellY*8+dy)
			sumR += float64(r) / 255
			sumG += float64(g) / 255
			sumB += float64(b) / 255
			sumBright += float64(max3(r, g, b)) / 255
		}
	}
	to8 := func(sum float64) uint8 {
		return uint8(math.Floor(sum/32*255 + 0.5))
	}
