		rows := h/2 - 1
		if rows < 0 {
			rows = 0
		}
		for cy := 0; cy < rows; cy++ {
			sy := cy*2 + 2
			for x := 0; x < w; x++ {
				ur, ug, ub := a.pixel(x, sy)
				lr, lg, lb := a.pixel(x, sy+1)
				fmt.Fprintf(&sb, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm▄", ur, ug, ub, lr, lg, lb)
			}
