			ch := ditherChar(a.dithering, bright)
			if a.noBG {
				fmt.Fprintf(&sb, "\x1b[38;2;%d;%d;%dm%c", r, g, b, ch)
			} else {
				fmt.Fprintf(&sb, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm%c", a.matte.R, a.matte.G, a.matte.B, r, g, b, ch)
			}
		}
		sb.WriteString("\x1b[0m\n")
	}
	return sb.String()
}

func goCode(s string) string {
	if s == "" {
		return ""
	}
	var sb strings.Builder
	lines := strings.SplitAfter(s, "\n")
	for _, line := range lines {
		if line == "" {
			continue
		}
		line = strings.ReplaceAll(line, "\x1b", "\\033")
		line = strings.ReplaceAll(line, "\n", "\\n")
		sb.WriteString("fmt.Print(\"")
		sb.WriteString(line)
		sb.WriteString("\")\n")
	}
	return sb.String()
}
