{"command":"cat > bmp.go << 'EOF'
package main

import (
	"encoding/binary"
	"errors"
	"image"
	"image/color"
	"io"
)

var errUnsupportedBMP = errors.New("bmp: unsupported BMP image")

func init() {
	image.RegisterFormat("bmp", "BM", decodeBMP, decodeBMPConfig)
}

type bmpHeader struct {
	dataOffset uint32
	width      int
	height     int
	topDown    bool
	bpp        uint16
	compression uint32
	colorsUsed uint32
	paletteOff int
}

func parseBMPHeader(data []byte) (*bmpHeader, error) {
	if len(data) < 18 {
		return nil, io.ErrUnexpectedEOF
	}
	if data[0] != 'B' || data[1] != 'M' {
		return nil, errUnsupportedBMP
	}
	h := &bmpHeader{dataOffset: binary.LittleEndian.Uint32(data[10:14])}
	dibSize := binary.LittleEndian.Uint32(data[14:18])
	if dibSize != 40 && dibSize != 108 && dibSize != 124 {
		return nil, errUnsupportedBMP
	}
	if len(data) < 14+int(dibSize) {
		return nil, io.ErrUnexpectedEOF
	}
	w := int32(binary.LittleEndian.Uint32(data[18:22]))
	ht := int32(binary.LittleEndian.Uint32(data[22:26]))
	planes := binary.LittleEndian.Uint16(data[26:28])
	h.bpp = binary.LittleEndian.Uint16(data[28:30])
	h.compression = binary.LittleEndian.Uint32(data[30:34])
	h.colorsUsed = binary.LittleEndian.Uint32(data[46:50])
	h.paletteOff = 14 + int(dibSize)
	if planes != 1 || h.compression != 0 || (h.bpp != 8 && h.bpp != 24 && h.bpp != 32) {
		return nil, errUnsupportedBMP
	}
	if w <= 0 || ht == 0 {
		return nil, errUnsupportedBMP
	}
	h.width = int(w)
	if ht < 0 {
		h.topDown = true
		h.height = int(-ht)
	} else {
		h.height = int(ht)
	}
	return h, nil
}

func decodeBMPConfig(r io.Reader) (image.Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	h, err := parseBMPHeader(data)
	if err != nil {
		return image.Config{}, err
	}
	return image.Config{ColorModel: color.RGBAModel, Width: h.width, Height: h.height}, nil
}

func decodeBMP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	h, err := parseBMPHeader(data)
	if err != nil {
		return nil, err
	}
	var palette []color.RGBA
	if h.bpp == 8 {
		n := int(h.colorsUsed)
		if n == 0 {
			n = 256
		}
		if n < 0 || n > 256 {
			return nil, errUnsupportedBMP
		}
		if len(data) < h.paletteOff+n*4 {
			return nil, io.ErrUnexpectedEOF
		}
		palette = make([]color.RGBA, n)
		for i := 0; i < n; i++ {
			off := h.paletteOff + i*4
			palette[i] = color.RGBA{R: data[off+2], G: data[off+1], B: data[off+0], A: 255}
		}
	}
	stride := ((int(h.bpp)*h.width + 31) / 32) * 4
	img := image.NewRGBA(image.Rect(0, 0, h.width, h.height))
	bytesPerPixel := int(h.bpp) / 8
	for y := 0; y < h.height; y++ {
		srcY := y
		if !h.topDown {
			srcY = h.height - 1 - y
		}
		rowOff := int(h.dataOffset) + srcY*stride
		if rowOff < 0 || rowOff+h.width*bytesPerPixel > len(data) {
			return nil, io.ErrUnexpectedEOF
		}
		for x := 0; x < h.width; x++ {
			off := rowOff + x*bytesPerPixel
			didx := y*img.Stride + x*4
			switch h.bpp {
			case 8:
				idx := data[off]
				c := color.RGBA{A: 255}
				if int(idx) < len(palette) {
					c = palette[idx]
				}
				img.Pix[didx+0], img.Pix[didx+1], img.Pix[didx+2], img.Pix[didx+3] = c.R, c.G, c.B, 255
			case 24, 32:
				img.Pix[didx+0] = data[off+2]
				img.Pix[didx+1] = data[off+1]
				img.Pix[didx+2] = data[off+0]
				img.Pix[didx+3] = 255
			}
		}
	}
	return img, nil
}
EOF

