import sys,subprocess,re
sys.path.insert(0,'/tmp/work')
from genfast import solid_png

def obs(W,H,maxW,maxH):
    # tc=maxW, tr=(maxH-2)//2 requires maxH even
    tc=maxW; tr=(maxH-2)//2
    solid_png('/tmp/work/x.png',W,H)
    r=subprocess.run(['/workspace/executable.orig','-s','2','-tc',str(tc),'-tr',str(tr),'/tmp/work/x.png'],capture_output=True)
    if r.returncode!=0:return ('err',r.stderr)
    lines=r.stdout.decode().splitlines()
    if not lines:return (0,0)
    cols=len(re.sub(r'\x1b\[[0-9;]*m','',lines[0])); rows=len(lines)
    return (rows,cols)

def candA(W,H,mw,mh):
    if W<=mw and H<=mh:return W,H
    # cross multiplication: width limiting if mw/W < mh/H => mw*H < mh*W
    if mw*H < mh*W:
        return mw,int(H*mw/W)
    else:
        return int(W*mh/H),mh

def candB(W,H,mw,mh):
    if W<=mw and H<=mh:return W,H
    aspect=W/H
    nh=mw/aspect
    if nh>mh:
        return int(mh*aspect),mh
    return mw,int(nh)

def candC(W,H,mw,mh):
    if W<=mw and H<=mh:return W,H
    # original current
    nw=mw;nh=int(H*mw/W)
    if nh>mh:
        nh=mh;nw=int(W*mh/H)
    return nw,nh

def candD(W,H,mw,mh):
    # scale round? trunc both but explicit max whichever ratio smaller using float scale comparisons
    if W<=mw and H<=mh:return W,H
    scaleW=mw/W;scaleH=mh/H
    if scaleW<scaleH:
        return mw,int(H*scaleW)  # H * (mw/W float)
    else:
        return int(W*scaleH),mh

def candE(W,H,mw,mh):
    # aspect but compute other dim as src*max/other multiplication (not aspect)
    if W<=mw and H<=mh:return W,H
    aspect=W/H
    if mw/aspect>mh:
        return int(W*mh/H),mh
    return mw,int(H*mw/W)

candidates={'A_cross_mult':candA,'B_aspect':candB,'C_current':candC,'D_scalefloat':candD,'E_aspectbranch_mult':candE}
scores={k:[0,0] for k in candidates}; examples={k:[] for k in candidates}
