            rows,cols=o
            # expected cols if candidate stage width = cols; stage height in [2rows+2,2rows+3] if rows>0; if rows==0, stage H is 2 or3 maybe cols0
            for name,fn in candidates.items():
                cw,ch=fn(W,H,maxW,maxH)
                ok=(cw==cols and ((rows==0 and ch in (2,3)) or (2*rows+2<=ch<=2*rows+3)))
                scores[name][1]+=1; scores[name][0]+=ok
                if not ok and len(examples[name])<5:examples[name].append((W,H,maxW,maxH,o,(cw,ch)))
print(scores)
for k,v in examples.items():print(k,v)
