		return nil, tiffUnsupported("compression")
	}
}

func decompressPackBits(data []byte) ([]byte, error) {
	var out []byte
	for i := 0; i < len(data); {
		n := int(int8(data[i]))
		i++
		switch {
		case n >= 0:
			if i+n+1 > len(data) {
				return nil, io.ErrUnexpectedEOF
			}
			out = append(out, data[i:i+n+1]...)
			i += n + 1
		case n == -128:
