			if i >= len(data) {
				return nil, io.ErrUnexpectedEOF
			}
			b := data[i]
			i++
			for k := 0; k < -n+1; k++ {
				out = append(out, b)
			}
		}
	}
	return out, nil
}

type bitReaderMSB struct {
	data []byte
	pos  int // bit position.
}

func (r *bitReaderMSB) read(n int) (uint32, bool) {
	if r.pos+n > len(r.data)*8 {
		return 0, false
	}
	var v uint32
	for i := 0; i < n; i++ {
		bytePos := (r.pos + i) / 8
		bitPos := 7 - uint((r.pos+i)%8)
		v = (v << 1) | uint32((r.data[bytePos]>>bitPos)&1)
	}
	r.pos += n
	return v, true
}

func decompressTIFFLZW(data []byte) ([]byte, error) {
	r := &bitReaderMSB{data: data}
