			}
			return img, nil
		}
		if b != 8 {
			// Convert other bit depths by scaling to 8 bits.
			img := image.NewRGBA(image.Rect(0, 0, w, h))
			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					i := y*img.Stride + x*4
					for c := 0; c < 3; c++ {
						img.Pix[i+c] = scaleSample(samples[y][x][c], b)
					}
					img.Pix[i+3] = 255
					if spp == 4 {
						img.Pix[i+3] = scaleSample(samples[y][x][3], b)
					}
				}
			}
			return img, nil
		}
		if spp == 4 && len(extra) > 0 && extra[0] == 2 {
			img := image.NewNRGBA(image.Rect(0, 0, w, h))
			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					i := y*img.Stride + x*4
					for c := 0; c < 4; c++ {
						img.Pix[i+c] = uint8(samples[y][x][c])
					}
				}
			}
			return img, nil
		}
		img := image.NewRGBA(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				i := y*img.Stride + x*4
				for c := 0; c < 3; c++ {
					img.Pix[i+c] = uint8(samples[y][x][c])
				}
				img.Pix[i+3] = 255
				if spp == 4 {
					img.Pix[i+3] = uint8(samples[y][x][3])
				}
			}
		}
		return img, nil
	case 4:
		// Transparency mask: render as a grayscale alpha shape
		// equivalent to decoding the mask as gray values.
		img := image.NewGray(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				img.Pix[y*img.Stride+x] = scaleSample(samples[y][x][0], bits[0])
			}
		}
		return img, nil
	case 6:
		return nil, errTIFFUnsupportedColor
	}
	return nil, fmt.Errorf("tiff: unsupported feature: photometric interpretation %d", photo)
}
