cat > tiff.go << 'EOF'
package main

import (
	"bytes"
	"compress/flate"
	"compress/zlib"
	"encoding/binary"
	"errors"
	"fmt"
	"image"
	"image/color"
	"io"
	"math"
)

func init() {
	image.RegisterFormat("tiff", "II*\x00", decodeTIFF, decodeTIFFConfig)
	image.RegisterFormat("tiffbe", "MM\x00*", decodeTIFF, decodeTIFFConfig)
}

var errTIFFUnsupportedColor = errors.New("tiff: unsupported feature: color model")

func tiffInvalid(msg string) error { return errors.New("tiff: invalid format: " + msg) }
func tiffUnsupported(msg string) error {
	return errors.New("tiff: unsupported feature: " + msg)
}

type tiffReader struct {
	data []byte
	ord  binary.ByteOrder
	tags map[uint16][]uint64
	raw  map[uint16][]byte
}

func (t *tiffReader) vals(tag uint16) ([]uint64, bool) {
	v, ok := t.tags[tag]
	return v, ok
}
func (t *tiffReader) val(tag uint16, def uint64) uint64 {
	if v, ok := t.tags[tag]; ok && len(v) > 0 {
		return v[0]
	}
	return def
}

var tiffTypeSizes = map[uint16]int{1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 6: 1, 7: 1, 8: 2, 9: 4, 10: 8, 11: 4, 12: 8, 13: 4, 16: 8, 17: 8, 18: 8}

func parseTIFF(data []byte) (*tiffReader, error) {
	if len(data) < 8 {
		return nil, io.ErrUnexpectedEOF
	}
	t := &tiffReader{data: data, tags: map[uint16][]uint64{}, raw: map[uint16][]byte{}}
	switch string(data[0:2]) {
	case "II":
		t.ord = binary.LittleEndian
	case "MM":
		t.ord = binary.BigEndian
	default:
		return nil, tiffInvalid("not a TIFF file")
	}
	if t.ord.Uint16(data[2:4]) != 42 {
		return nil, tiffInvalid("not a TIFF file")
	}
	ifdOff := int(t.ord.Uint32(data[4:8]))
	if ifdOff < 0 || ifdOff+2 > len(data) {
		return nil, io.ErrUnexpectedEOF
	}
	n := int(t.ord.Uint16(data[ifdOff : ifdOff+2]))
	pos := ifdOff + 2
	for i := 0; i < n; i++ {
		if pos+12 > len(data) {
			return nil, io.ErrUnexpectedEOF
		}
		tag := t.ord.Uint16(data[pos : pos+2])
		typ := t.ord.Uint16(data[pos+2 : pos+4])
		count := t.ord.Uint32(data[pos+4 : pos+8])
		sz, ok := tiffTypeSizes[typ]
		if !ok {
			pos += 12
			continue
		}
		total := int(count) * sz
		var raw []byte
		if total <= 4 {
			raw = data[pos+8 : pos+8+total]
		} else {
			off := int(t.ord.Uint32(data[pos+8 : pos+12]))
			if off < 0 || off+total > len(data) {
				return nil, io.ErrUnexpectedEOF
			}
			raw = data[off : off+total]
		}
		t.raw[tag] = append([]byte(nil), raw...)
		vals := make([]uint64, 0, count)
		for j := 0; j < int(count); j++ {
			off := j * sz
			if off+sz > len(raw) {
				break
			}
			switch sz {
			case 1:
				vals = append(vals, uint64(raw[off]))
			case 2:
				vals = append(vals, uint64(t.ord.Uint16(raw[off:])))
			case 4:
				if typ == 11 {
					vals = append(vals, uint64(math.Float32bits(math.Float32frombits(t.ord.Uint32(raw[off:])))))
				} else {
					vals = append(vals, uint64(t.ord.Uint32(raw[off:])))
				}
			case 8:
				if typ == 5 || typ == 10 {
					// Store numerator only for tags used here; rationals are otherwise ignored.
					vals = append(vals, uint64(t.ord.Uint32(raw[off:])))
				} else {
					vals = append(vals, t.ord.Uint64(raw[off:]))
				}
			}
		}
		t.tags[tag] = vals
		pos += 12
	}
	return t, nil
}

func decodeTIFFConfig(r io.Reader) (image.Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	t, err := parseTIFF(data)
	if err != nil {
		return image.Config{}, err
	}
	w := int(t.val(256, 0))
	h := int(t.val(257, 0))
	return image.Config{ColorModel: color.RGBAModel, Width: w, Height: h}, nil
}

func decompressTIFF(comp uint64, data []byte) ([]byte, error) {
	switch comp {
	case 1:
		return data, nil
	case 5: // LZW.
		return decompressTIFFLZW(data)
	case 32773: // PackBits.
		return decompressPackBits(data)
	case 8, 32946: // Deflate (Adobe / old).
		zr, err := zlib.NewReader(bytes.NewReader(data))
		if err != nil {
			fr := flate.NewReader(bytes.NewReader(data))
			defer fr.Close()
			return io.ReadAll(fr)
		}
		defer zr.Close()
		return io.ReadAll(zr)
	default:
		return nil, tiffUnsupported("compression")
	}
}

func decompressPackBits(data []byte) ([]byte, error) {
	var out []byte
	for i := 0; i < len(data); {
		n := int(int8(data[i]))
		i++
		switch {
		case n >= 0:
			if i+n+1 > len(data) {
				return nil, io.ErrUnexpectedEOF
			}
			out = append(out, data[i:i+n+1]...)
			i += n + 1
		case n == -128:
		default:
			if i >= len(data) {
				return nil, io.ErrUnexpectedEOF
			}
			b := data[i]
			i++
			for k := 0; k < -n+1; k++ {
				out = append(out, b)
			}
		}
	}
	return out, nil
}

type bitReaderMSB struct {
	data []byte
	pos  int // bit position.
}

func (r *bitReaderMSB) read(n int) (uint32, bool) {
	if r.pos+n > len(r.data)*8 {
		return 0, false
	}
	var v uint32
	for i := 0; i < n; i++ {
		bytePos := (r.pos + i) / 8
		bitPos := 7 - uint((r.pos+i)%8)
		v = (v << 1) | uint32((r.data[bytePos]>>bitPos)&1)
	}
	r.pos += n
	return v, true
}

func decompressTIFFLZW(data []byte) ([]byte, error) {
	r := &bitReaderMSB{data: data}
	dict := make([][]byte, 0, 4096)
	reset := func() {
		dict = dict[:0]
		for i := 0; i < 256; i++ {
			dict = append(dict, []byte{byte(i)})
		}
		dict = append(dict, nil, nil) // 256 clear, 257 EOI.
	}
	reset()
	var out []byte
	var prev []byte
	codeSize := 9
	for {
		code, ok := r.read(codeSize)
		if !ok {
			break
		}
		if code == 256 {
			reset()
			prev = nil
			codeSize = 9
			continue
		}
		if code == 257 {
			break
		}
		var entry []byte
		if int(code) < len(dict) && dict[code] != nil {
			entry = dict[code]
		} else if int(code) == len(dict) && prev != nil {
			entry = append(append([]byte(nil), prev...), prev[0])
		} else {
			return nil, errors.New("tiff: invalid LZW code")
		}
		out = append(out, entry...)
		if prev != nil {
			dict = append(dict, append(append([]byte(nil), prev...), entry[0]))
			// Early-change LZW increases the code width one entry
			// before the dictionary is completely full.
			if len(dict)+1 >= (1<<codeSize) && codeSize < 12 {
				codeSize++
			}
		}
		prev = entry
		if len(dict) >= 4096 {
			// Continue decoding without adding until a clear code.
			// Clamp prev-add effect by not growing above 4096.
			dict = dict[:4096]
		}
	}
	return out, nil
}

func decodeTIFF(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	t, err := parseTIFF(data)
	if err != nil {
		return nil, err
	}
	w := int(t.val(256, 0))
	h := int(t.val(257, 0))
	if w <= 0 || h <= 0 {
		return nil, tiffInvalid("missing image size")
	}
	bitsList, _ := t.vals(258)
	if len(bitsList) == 0 {
		bitsList = []uint64{1}
	}
	comp := t.val(259, 1)
	photo := t.val(262, 0)
	if _, ok := t.tags[262]; !ok {
		return nil, tiffInvalid("missing photometric interpretation")
	}
	spp := int(t.val(277, 1))
	planar := t.val(284, 1)
	predictor := t.val(317, 1)
	if spp <= 0 {
		return nil, tiffInvalid("wrong number of samples")
	}
	bits := make([]int, spp)
	for i := range bits {
		if i < len(bitsList) {
			bits[i] = int(bitsList[i])
		} else {
			bits[i] = int(bitsList[0])
		}
		if bits[i] <= 0 || bits[i] > 32 {
			return nil, tiffUnsupported("bits per sample")
		}
	}
	sampleFormats, _ := t.vals(339)
	for i := 0; i < spp && i < len(sampleFormats); i++ {
		if sampleFormats[i] != 1 {
			// Signed and floating point TIFFs are uncommon in the
			// target cases and are treated as unsupported rather
			// than silently rendered incorrectly.
			return nil, tiffUnsupported("sample format")
		}
	}
	if photo == 5 || photo == 8 {
		return nil, errTIFFUnsupportedColor
	}
	if photo != 0 && photo != 1 && photo != 2 && photo != 3 && photo != 4 && photo != 6 {
		return nil, errTIFFUnsupportedColor
	}
	extra, hasExtra := t.vals(338)
	if photo == 2 {
		if spp < 3 || spp > 4 || (spp == 4 && (!hasExtra || len(extra) == 0 || extra[0] == 0)) {
			return nil, tiffInvalid("wrong number of samples for RGB")
		}
	}
	// Collect segments in planar order.
	type segment struct {
		data []byte
		x, y int
		w, h int
		plane int
	}
	var segments []segment
	isTiled := false
	if _, ok := t.tags[322]; ok {
		isTiled = true
	}
	if isTiled {
		tw := int(t.val(322, 0))
		th := int(t.val(323, 0))
		offsets, _ := t.vals(324)
		counts, _ := t.vals(325)
		if tw <= 0 || th <= 0 || len(offsets) == 0 {
			return nil, tiffInvalid("missing tiles")
		}
		tilesX := (w + tw - 1) / tw
		tilesY := (h + th - 1) / th
		idx := 0
		planes := 1
		if planar == 2 {
			planes = spp
		}
		for p := 0; p < planes; p++ {
			for ty := 0; ty < tilesY; ty++ {
				for tx := 0; tx < tilesX; tx++ {
					if idx >= len(offsets) {
						return nil, io.ErrUnexpectedEOF
					}
					off := int(offsets[idx])
					cnt := 0
					if idx < len(counts) {
						cnt = int(counts[idx])
					}
					if off < 0 || cnt < 0 || off+cnt > len(data) {
						return nil, io.ErrUnexpectedEOF
					}
					dec, err := decompressTIFF(comp, data[off:off+cnt])
					if err != nil {
						return nil, err
					}
					segments = append(segments, segment{dec, tx * tw, ty * th, tw, th, p})
					idx++
				}
			}
		}
	} else {
		rowsPerStrip := int(t.val(278, uint64(h)))
		if rowsPerStrip <= 0 {
			rowsPerStrip = h
		}
		offsets, _ := t.vals(273)
		counts, _ := t.vals(279)
		if len(offsets) == 0 {
			return nil, tiffInvalid("missing strips")
		}
		planes := 1
		if planar == 2 {
			planes = spp
		}
		idx := 0
		for p := 0; p < planes; p++ {
			for y := 0; y < h; y += rowsPerStrip {
				if idx >= len(offsets) {
					return nil, io.ErrUnexpectedEOF
				}
				off := int(offsets[idx])
				cnt := 0
				if idx < len(counts) {
					cnt = int(counts[idx])
				} else {
					cnt = len(data) - off
				}
				if off < 0 || cnt < 0 || off+cnt > len(data) {
					return nil, io.ErrUnexpectedEOF
				}
				dec, err := decompressTIFF(comp, data[off:off+cnt])
				if err != nil {
					return nil, err
				}
				sh := rowsPerStrip
				if y+sh > h {
					sh = h - y
				}
				segments = append(segments, segment{dec, 0, y, w, sh, p})
				idx++
			}
		}
	}
	// Extract unsigned integer samples.
	samples := make([][][]uint32, h)
	for y := range samples {
		samples[y] = make([][]uint32, w)
		for x := range samples[y] {
			samples[y][x] = make([]uint32, spp)
		}
	}
	for _, seg := range segments {
		// Segment sample dimensions, accounting for planar data.
		segSamplesPerPixel := spp
		if planar == 2 {
			segSamplesPerPixel = 1
		}
		br := &bitReaderMSB{data: seg.data}
		rows := make([][][]uint32, seg.h)
		for yy := 0; yy < seg.h; yy++ {
			br.pos = ((br.pos + 7) / 8) * 8
			row := make([][]uint32, seg.w)
			for xx := 0; xx < seg.w; xx++ {
				vals := make([]uint32, segSamplesPerPixel)
				for s := 0; s < segSamplesPerPixel; s++ {
					b := bits[s]
					if planar == 2 {
						b = bits[seg.plane]
					}
					if b == 8 || b == 16 || b == 32 {
						// Fast aligned path below via bit reader also works,
						// but endianness for >8 bits is handled separately.
					}
					if b > 8 && b%8 == 0 {
						nb := b / 8
						if br.pos%8 != 0 {
							return nil, tiffUnsupported("sample alignment")
						}
						bytePos := br.pos / 8
						if bytePos+nb > len(seg.data) {
							return nil, io.ErrUnexpectedEOF
						}
						var v uint32
						for k := 0; k < nb; k++ {
							if t.ord == binary.LittleEndian {
								v |= uint32(seg.data[bytePos+k]) << (8 * k)
							} else {
								v = (v << 8) | uint32(seg.data[bytePos+k])
							}
						}
						br.pos += b
						vals[s] = v
					} else {
						v, ok := br.read(b)
						if !ok {
							return nil, io.ErrUnexpectedEOF
						}
						vals[s] = v
					}
				}
				row[xx] = vals
			}
			rows[yy] = row
		}
		if predictor == 2 {
			for yy := range rows {
				for xx := 1; xx < len(rows[yy]); xx++ {
					for s := range rows[yy][xx] {
						b := bits[s]
						if planar == 2 {
							b = bits[seg.plane]
						}
						mask := uint32(0xffffffff)
						if b < 32 {
							mask = (1 << uint(b)) - 1
						}
						rows[yy][xx][s] = (rows[yy][xx][s] + rows[yy][xx-1][s]) & mask
					}
				}
			}
		} else if predictor != 1 {
			return nil, tiffUnsupported("predictor")
		}
		for yy := range rows {
			gy := seg.y + yy
			if gy < 0 || gy >= h {
				continue
			}
			for xx := range rows[yy] {
				gx := seg.x + xx
				if gx < 0 || gx >= w {
					continue
				}
				if planar == 2 {
					samples[gy][gx][seg.plane] = rows[yy][xx][0]
				} else {
					copy(samples[gy][gx], rows[yy][xx])
				}
			}
		}
	}
	return tiffSamplesToImage(t, samples, w, h, spp, bits, int(photo), extra)
}

func scaleSample(v uint32, bits int) uint8 {
	if bits == 8 {
		return uint8(v)
	}
	if bits < 8 {
		maxv := uint32((1 << uint(bits)) - 1)
		if maxv == 0 {
			return 0
		}
		return uint8(v * 255 / maxv)
	}
	return uint8(v >> uint(bits-8))
}

func tiffSamplesToImage(t *tiffReader, samples [][][]uint32, w, h, spp int, bits []int, photo int, extra []uint64) (image.Image, error) {
	switch photo {
	case 0, 1:
		if spp != 1 {
			return nil, tiffInvalid("wrong number of samples for grayscale")
		}
		b := bits[0]
		if b == 16 {
			img := image.NewGray16(image.Rect(0, 0, w, h))
			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					v := uint16(samples[y][x][0])
					if photo == 0 {
						v = 65535 - v
					}
					i := y*img.Stride + x*2
					img.Pix[i] = uint8(v >> 8)
					img.Pix[i+1] = uint8(v)
				}
			}
			return img, nil
		}
		img := image.NewGray(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := samples[y][x][0]
				if photo == 0 {
					if b < 32 {
						v = ((1 << uint(b)) - 1) - v
					} else {
						v = 0xffffffff - v
					}
				}
				img.Pix[y*img.Stride+x] = scaleSample(v, b)
			}
		}
		return img, nil
	case 3:
		if spp != 1 {
			return nil, tiffInvalid("wrong number of samples for palette")
		}
		rawmap, ok := t.raw[320]
		if !ok {
			return nil, tiffInvalid("missing color map")
		}
		num := 1
		if bits[0] < 31 {
			num = 1 << uint(bits[0])
		}
		if len(rawmap) < num*3*2 {
			return nil, io.ErrUnexpectedEOF
		}
		pal := make(color.Palette, num)
		for i := 0; i < num; i++ {
			r := t.ord.Uint16(rawmap[i*2:])
			g := t.ord.Uint16(rawmap[(num+i)*2:])
			b := t.ord.Uint16(rawmap[(2*num+i)*2:])
			pal[i] = color.RGBA{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8), 255}
		}
		img := image.NewPaletted(image.Rect(0, 0, w, h), pal)
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := samples[y][x][0]
				if v > 255 {
					v = 255
				}
				// Palette entries can be up to 65536 for 16-bit indices,
				// but Go paletted images store one byte indices. Such
				// TIFFs are very uncommon; 8-bit palette indices are
				// the supported common case.
				img.Pix[y*img.Stride+x] = uint8(v)
			}
		}
		return img, nil
	case 2:
		b := bits[0]
		for _, bb := range bits {
			if bb != b {
				return nil, tiffUnsupported("differing bits per sample")
			}
		}
		if b == 16 {
			if spp == 4 && len(extra) > 0 && extra[0] == 2 {
				img := image.NewNRGBA64(image.Rect(0, 0, w, h))
				for y := 0; y < h; y++ {
					for x := 0; x < w; x++ {
						i := y*img.Stride + x*8
						for c := 0; c < 4; c++ {
							v := uint16(samples[y][x][c])
