func decodeTIFFConfig(r io.Reader) (image.Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	t, err := parseTIFF(data)
	if err != nil {
		return image.Config{}, err
	}
	w := int(t.val(256, 0))
	h := int(t.val(257, 0))
