}

func scaleSample(v uint32, bits int) uint8 {
	if bits == 8 {
		return uint8(v)
	}
	if bits < 8 {
		maxv := uint32((1 << uint(bits)) - 1)
		if maxv == 0 {
			return 0
		}
		return uint8(v * 255 / maxv)
	}
	return uint8(v >> uint(bits-8))
}

func tiffSamplesToImage(t *tiffReader, samples [][][]uint32, w, h, spp int, bits []int, photo int, extra []uint64) (image.Image, error) {
	switch photo {
	case 0, 1:
		if spp != 1 {
			return nil, tiffInvalid("wrong number of samples for grayscale")
		}
		b := bits[0]
		if b == 16 {
			img := image.NewGray16(image.Rect(0, 0, w, h))
			for y := 0; y < h; y++ {
				for x := 0; x < w; x++ {
					v := uint16(samples[y][x][0])
					if photo == 0 {
						v = 65535 - v
					}
					i := y*img.Stride + x*2
					img.Pix[i] = uint8(v >> 8)
					img.Pix[i+1] = uint8(v)
				}
			}
			return img, nil
		}
		img := image.NewGray(image.Rect(0, 0, w, h))
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := samples[y][x][0]
				if photo == 0 {
					if b < 32 {
						v = ((1 << uint(b)) - 1) - v
					} else {
						v = 0xffffffff - v
					}
				}
				img.Pix[y*img.Stride+x] = scaleSample(v, b)
			}
		}
		return img, nil
	case 3:
		if spp != 1 {
			return nil, tiffInvalid("wrong number of samples for palette")
		}
		rawmap, ok := t.raw[320]
		if !ok {
			return nil, tiffInvalid("missing color map")
		}
		num := 1
		if bits[0] < 31 {
			num = 1 << uint(bits[0])
		}
		if len(rawmap) < num*3*2 {
			return nil, io.ErrUnexpectedEOF
		}
		pal := make(color.Palette, num)
		for i := 0; i < num; i++ {
			r := t.ord.Uint16(rawmap[i*2:])
			g := t.ord.Uint16(rawmap[(num+i)*2:])
			b := t.ord.Uint16(rawmap[(2*num+i)*2:])
			pal[i] = color.RGBA{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8), 255}
		}
		img := image.NewPaletted(image.Rect(0, 0, w, h), pal)
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := samples[y][x][0]
				if v > 255 {
					v = 255
				}
