				// but Go paletted images store one byte indices. Such
				// TIFFs are very uncommon; 8-bit palette indices are
				// the supported common case.
				img.Pix[y*img.Stride+x] = uint8(v)
			}
		}
		return img, nil
	case 2:
		b := bits[0]
		for _, bb := range bits {
			if bb != b {
