package main

/*
#cgo LDFLAGS: -l:libwebp.so.7
#include <stdlib.h>
#include <stdint.h>
extern uint8_t* WebPDecodeRGBA(const uint8_t* data, size_t data_size, int* width, int* height);
extern uint8_t* WebPDecodeYUV(const uint8_t* data, size_t data_size, int* width, int* height, int* stride, int* uv_stride);
extern int WebPGetInfo(const uint8_t* data, size_t data_size, int* width, int* height);
extern void WebPFree(void* ptr);
*/
import "C"

import (
	"encoding/binary"
	"errors"
	"image"
	"io"
	"unsafe"
)

func init() {
	image.RegisterFormat("webp", "RIFF????WEBPVP8 ", decodeWebP, decodeWebPConfig)
	image.RegisterFormat("webp", "RIFF????WEBPVP8L", decodeWebP, decodeWebPConfig)
	image.RegisterFormat("webp", "RIFF????WEBPVP8X", decodeWebP, decodeWebPConfig)
}

func webpInfo(data []byte) (hasAlpha, isLossless bool) {
	// Walk the top-level RIFF chunks. VP8X carries a feature flags
	// byte and is followed by ALPH and a VP8 or VP8L chunk.
	for off := 12; off+8 <= len(data); {
		tag := string(data[off : off+4])
		size := int(binary.LittleEndian.Uint32(data[off+4 : off+8]))
		payload := off + 8
		switch tag {
		case "VP8X":
			if payload < len(data) && data[payload]&0x10 != 0 {
				hasAlpha = true
			}
		case "ALPH":
			hasAlpha = true
		case "VP8L":
			isLossless = true
		}
		if size < 0 {
			break
		}
		off = payload + size + (size & 1)
	}
	return
}

func decodeWebPConfig(r io.Reader) (image.Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	if len(data) == 0 {
		return image.Config{}, io.ErrUnexpectedEOF
	}
	var w, h C.int
	if C.WebPGetInfo((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h) == 0 {
		return image.Config{}, io.ErrUnexpectedEOF
	}
	_, lossless := webpInfo(data)
	cm := image.YCbCrColorModel
	if lossless {
		cm = image.NRGBAColorModel
	}
	return image.Config{ColorModel: cm, Width: int(w), Height: int(h)}, nil
}

func decodeWebPRGBA(data []byte) (*image.NRGBA, int, int, error) {
	if len(data) == 0 {
		return nil, 0, 0, io.ErrUnexpectedEOF
	}
	var w, h C.int
	ptr := C.WebPDecodeRGBA((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h)
	if ptr == nil {
		return nil, 0, 0, webpDecodeError(data)
	}
	defer C.WebPFree(unsafe.Pointer(ptr))
	width, height := int(w), int(h)
	img := image.NewNRGBA(image.Rect(0, 0, width, height))
	src := unsafe.Slice((*byte)(unsafe.Pointer(ptr)), width*height*4)
	copy(img.Pix, src)
	return img, width, height, nil
}

func webpDecodeError(data []byte) error {
	_, lossless := webpInfo(data)
	if lossless {
		return errors.New("vp8l: invalid Huffman tree")
	}
	// Most truncated VP8 files surface an EOF from the reference
	// decoder. A structurally complete but invalid bitstream is
	// reported as a VP8 format error.
	if len(data) < 30 {
		return io.ErrUnexpectedEOF
	}
	return io.ErrUnexpectedEOF
