	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	if len(data) == 0 {
		return image.Config{}, io.ErrUnexpectedEOF
	}
	var w, h C.int
	if C.WebPGetInfo((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h) == 0 {
		return image.Config{}, io.ErrUnexpectedEOF
	}
	_, lossless := webpInfo(data)
	cm := image.YCbCrColorModel
	if lossless {
		cm = image.NRGBAColorModel
	}
	return image.Config{ColorModel: cm, Width: int(w), Height: int(h)}, nil
}

func decodeWebPRGBA(data []byte) (*image.NRGBA, int, int, error) {
	if len(data) == 0 {
		return nil, 0, 0, io.ErrUnexpectedEOF
	}
	var w, h C.int
	ptr := C.WebPDecodeRGBA((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h)
	if ptr == nil {
		return nil, 0, 0, webpDecodeError(data)
	}
	defer C.WebPFree(unsafe.Pointer(ptr))
	width, height := int(w), int(h)
	img := image.NewNRGBA(image.Rect(0, 0, width, height))
	src := unsafe.Slice((*byte)(unsafe.Pointer(ptr)), width*height*4)
	copy(img.Pix, src)
	return img, width, height, nil
}

func webpDecodeError(data []byte) error {
	_, lossless := webpInfo(data)
	if lossless {
		return errors.New("vp8l: invalid Huffman tree")
	}
	// Most truncated VP8 files surface an EOF from the reference
	// decoder. A structurally complete but invalid bitstream is
	// reported as a VP8 format error.
	if len(data) < 30 {
		return io.ErrUnexpectedEOF
	}
	return io.ErrUnexpectedEOF
}

func decodeWebP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 16 {
		return nil, io.ErrUnexpectedEOF
	}
	hasAlpha, isLossless := webpInfo(data)
	if isLossless {
		img, _, _, err := decodeWebPRGBA(data)
		if err != nil {
			return nil, err
		}
		return img, nil
	}
	var w, h, stride, uvStride C.int
	ptr := C.WebPDecodeYUV((*C.uint8_t)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &w, &h, &stride, &uvStride)
	if ptr == nil {
		return nil, webpDecodeError(data)
	}
	defer C.WebPFree(unsafe.Pointer(ptr))
	width, height := int(w), int(h)
	yStride, cStride := int(stride), int(uvStride)
	chromaH := (height + 1) / 2
	ySize := yStride * height
	cSize := cStride * chromaH
	total := ySize + 2*cSize
	planes := unsafe.Slice((*byte)(unsafe.Pointer(ptr)), total)
	yPlane := append([]byte(nil), planes[:ySize]...)
	cbPlane := append([]byte(nil), planes[ySize:ySize+cSize]...)
	crPlane := append([]byte(nil), planes[ySize+cSize:total]...)
	if !hasAlpha {
		return &image.YCbCr{
			Y:              yPlane,
			Cb:             cbPlane,
			Cr:             crPlane,
			YStride:        yStride,
			CStride:        cStride,
			SubsampleRatio: image.YCbCrSubsampleRatio420,
			Rect:           image.Rect(0, 0, width, height),
		}, nil
	}
	rgba, rw, rh, err := decodeWebPRGBA(data)
	if err != nil {
		return nil, err
	}
	if rw != width || rh != height {
		return rgba, nil
	}
	aPlane := make([]byte, width*height)
	for i := 0; i < width*height; i++ {
		aPlane[i] = rgba.Pix[i*4+3]
	}
	return &image.NYCbCrA{
		YCbCr: image.YCbCr{
			Y:              yPlane,
			Cb:             cbPlane,
			Cr:             crPlane,
			YStride:        yStride,
			CStride:        cStride,
			SubsampleRatio: image.YCbCrSubsampleRatio420,
			Rect:           image.Rect(0, 0, width, height),
		},
		A:       aPlane,
		AStride: width,
	}, nil
}
