def sinc_a(x): # our original in python candidate: sin(pi*x)/(pi*x) * sin(pi*x/3)/(pi*x/3) [candidate.py uses this expression]
    if x==0:return 1
    if -3<x<3:return (math.sin(math.pi*x)/(math.pi*x))*(math.sin(math.pi*x/3)/(math.pi*x/3))
    return 0
def sinc_b(x):
    def s(t):return 1 if t==0 else math.sin(math.pi*t)/(math.pi*t)
    if -3<x<3:return s(x)*s(x/3)
    return 0
