import struct

def build(path,w,h,pixel_segments,tags_base):
    # pixel_segments is data after IFD & extra arrays, in file order; tags_base entries exclude offset/count tags handled separately
    pass

def make_tiff(path,entries,data_segments):
    # entries list tuples (tag,type,values raw python list); values for offsets tags will be patched with segment offsets sequentially if value == 'SEG'
    # Layout: header8, IFD, extra values, then segments.
    n=len(entries); ifd_size=2+n*12+4; cur=8+ifd_size; extra=b''; entry_objs=[]
    # Precompute raw for non-seg entries to know extra length
    raws=[]
    for tag,typ,vals in entries:
        if typ==3: raw=b''.join(struct.pack('<H',v) for v in vals)
        elif typ==4: raw=b''.join(struct.pack('<I',v if isinstance(v,int) else 0) for v in vals)
        else: raw=bytes(vals)
        raws.append(raw)
        if len(raw)>4:
            cur+=len(raw)+(len(raw)%2);extra+=raw+(b'\x00' if len(raw)%2 else b'')
    seg_offsets=[]; databytes=b''
    for seg in data_segments:
        seg_offsets.append(cur);databytes+=seg;cur+=len(seg)
    # rebuild entries patching SEG placeholders in order
    seg_i=0; extra=b''; cur=8+ifd_size; out_entries=b''
    for (tag,typ,vals),raw in zip(entries,raws):
        # patch vals if sentinel -1 means next segment offset
        vals2=[]
        changed=False
        for v in vals:
            if v==-1: vals2.append(seg_offsets[seg_i]);seg_i+=1;changed=True
            else: vals2.append(v)
        if typ==3: raw=b''.join(struct.pack('<H',v) for v in vals2)
        elif typ==4: raw=b''.join(struct.pack('<I',v) for v in vals2)
        if len(raw)<=4: val=raw+b'\x00'*(4-len(raw))
        else: val=struct.pack('<I',cur);extra+=raw+(b'\x00' if len(raw)%2 else b'');cur+=len(raw)+(len(raw)%2)
        out_entries+=struct.pack('<HHI',tag,typ,len(vals2))+val
    out=b'II*\x00'+struct.pack('<I',8)+struct.pack('<H',n)+out_entries+struct.pack('<I',0)+extra+databytes
    open(path,'wb').write(out)
