    elif name=='W2':
        fx=(d+0.5)/inv
        for i in range(W):
            arg=(fx-(i+0.5))*inv;w=lanczos(arg)
            if w:ws.append((i,w))
    elif name=='W3':
        fu=d/inv + (1/inv-1)/2
        for i in range(W):
            arg=(i-fu)*inv;w=lanczos(arg)
            if w:ws.append((i,w))
    elif name=='W4':
        center=(d+0.5)/inv-0.5
        for i in range(W):
            arg=(i-center)*inv;w=lanczos(arg)
            if w:ws.append((i,w))
    elif name=='W5':
        recip=1/scale_down;fx=(d+0.5)*scale_down
        for i in range(W):
            arg=(fx-(i+0.5))*recip;w=lanczos(arg)
            if w:ws.append((i,w))
