		center := (float64(dst) + 0.5) / ratio
		start := int(math.Floor(center - support))
		if start < 0 {
			start = 0
		}
		stop := int(math.Ceil(center + support))
		if stop > srcSize {
			stop = srcSize
		}
		var ws []resizeWeight
		var sum float64
		for src := start; src < stop; src++ {
			w := lanczosKernel((float64(src) + 0.5 - center) * kernelScale)
			if w != 0 {
				ws = append(ws, resizeWeight{index: src, weight: w})
				sum += w
			}
		}
		if sum != 0 {
			for i := range ws {
				ws[i].weight /= sum
			}
